/**
 * # Static tooltips
 *
 * A delegated, portal-free tooltip for content that ships **no
 * client-side JS**.
 *
 * ## Why this exists
 *
 * `Tooltip` wraps its trigger in a Radix tooltip, which only ever
 * appears once React has hydrated. Detail pages, listing cards,
 * featured stars and author marks all render statically — Astro turns
 * their React tree into HTML at build time and ships nothing — so every
 * tooltip outside the `Header` island was silently inert.
 *
 * A CSS-only tooltip was tried first and does not work here: the
 * immediate parent of the detail link row (`.esc-detail-link-section`)
 * sets `overflow-x: auto`, a deliberate small-screen affordance. An
 * absolutely-positioned pseudo-element is clipped by that ancestor *and*
 * extends its scrollable width, so the tooltip never shows and a stray
 * horizontal scrollbar appears. Escaping an overflow ancestor is exactly
 * what Radix's Portal does; this module does the same thing the cheap
 * way — one `position: fixed` node parented to `<body>`.
 *
 * ## How it coexists with Radix
 *
 * `Tooltip` renders `data-tooltip` on its trigger during SSR and drops
 * the attribute in an effect, which only runs once hydrated. So exactly
 * one implementation is live per element: static markup keeps the
 * attribute and is handled here; a hydrated island loses it and is
 * handled by Radix. Both share the animation keyframes and box styling
 * in `base.css`, so they look identical.
 *
 * ## Usage
 *
 * Once per page, from the site's shell:
 *
 * ```astro
 * <script>
 *   import { initTooltips } from "@semio-community/ecosystem-site-core/tooltip";
 *   initTooltips();
 * </script>
 * ```
 */
const TRIGGER_SELECTOR = "[data-tooltip]";
const SHOW_DELAY_MS = 150;
const SIDE_OFFSET_PX = 6;
const VIEWPORT_MARGIN_PX = 4;
let layer = null;
let activeTrigger = null;
let showTimer;
let initialized = false;
function ensureLayer() {
    if (layer?.isConnected)
        return layer;
    const node = document.createElement("div");
    // `tooltip-content` carries the shared directional animations; the
    // Radix copy uses the same class for the same reason.
    node.className = "tooltip-content esc-tooltip";
    node.setAttribute("role", "tooltip");
    node.hidden = true;
    document.body.appendChild(node);
    layer = node;
    return node;
}
function position(trigger, node, side) {
    const rect = trigger.getBoundingClientRect();
    const { width, height } = node.getBoundingClientRect();
    let resolvedSide = side;
    let top = side === "top"
        ? rect.top - height - SIDE_OFFSET_PX
        : rect.bottom + SIDE_OFFSET_PX;
    // Flip when the preferred side has no room, then clamp so the tooltip
    // stays on screen even if neither side fits.
    if (side === "top" && top < VIEWPORT_MARGIN_PX) {
        resolvedSide = "bottom";
        top = rect.bottom + SIDE_OFFSET_PX;
    }
    else if (side === "bottom" &&
        top + height > window.innerHeight - VIEWPORT_MARGIN_PX) {
        resolvedSide = "top";
        top = rect.top - height - SIDE_OFFSET_PX;
    }
    const anchorX = rect.left + rect.width / 2;
    const maxLeft = window.innerWidth - width - VIEWPORT_MARGIN_PX;
    const left = Math.min(Math.max(anchorX - width / 2, VIEWPORT_MARGIN_PX), Math.max(maxLeft, VIEWPORT_MARGIN_PX));
    node.dataset.side = resolvedSide;
    node.style.top = `${Math.round(top)}px`;
    node.style.left = `${Math.round(left)}px`;
    // The arrow tracks the trigger rather than the box, so it stays
    // pointed at the button when the box is clamped to a viewport edge.
    node.style.setProperty("--esc-tooltip-arrow-x", `${Math.round(Math.min(Math.max(anchorX - left, 8), Math.max(width - 8, 8)))}px`);
}
function show(trigger) {
    const text = trigger.getAttribute("data-tooltip");
    if (!text)
        return;
    const node = ensureLayer();
    activeTrigger = trigger;
    node.textContent = text;
    node.hidden = false;
    // Retrigger the entry animation for each new trigger.
    node.removeAttribute("data-state");
    void node.offsetWidth;
    node.dataset.state = "delayed-open";
    position(trigger, node, trigger.getAttribute("data-tooltip-side") === "bottom" ? "bottom" : "top");
}
function hide() {
    clearTimeout(showTimer);
    showTimer = undefined;
    activeTrigger = null;
    if (!layer)
        return;
    layer.hidden = true;
    layer.removeAttribute("data-state");
}
function scheduleShow(trigger, delay) {
    if (activeTrigger === trigger)
        return;
    clearTimeout(showTimer);
    if (delay <= 0) {
        show(trigger);
        return;
    }
    showTimer = setTimeout(() => show(trigger), delay);
}
function findTrigger(target) {
    if (!(target instanceof Element))
        return null;
    return target.closest(TRIGGER_SELECTOR);
}
/**
 * Attach the document-level listeners. Safe to call more than once and
 * safe to call before `DOMContentLoaded`; a no-op outside the browser.
 */
export function initTooltips() {
    if (initialized || typeof document === "undefined")
        return;
    initialized = true;
    document.addEventListener("pointerover", (event) => {
        // Touch has no hover state, and a tap would leave the tooltip
        // stranded over the content it describes.
        if (event.pointerType === "touch")
            return;
        const trigger = findTrigger(event.target);
        if (!trigger) {
            if (activeTrigger)
                hide();
            return;
        }
        scheduleShow(trigger, SHOW_DELAY_MS);
    }, true);
    document.addEventListener("pointerout", (event) => {
        if (!activeTrigger && !showTimer)
            return;
        const next = findTrigger(event.relatedTarget);
        if (next && next === findTrigger(event.target))
            return;
        hide();
    }, true);
    // Keyboard users get the tooltip without the hover delay.
    document.addEventListener("focusin", (event) => {
        const trigger = findTrigger(event.target);
        if (trigger)
            scheduleShow(trigger, 0);
        else if (activeTrigger)
            hide();
    });
    document.addEventListener("focusout", () => hide());
    document.addEventListener("click", () => hide());
    document.addEventListener("keydown", (event) => {
        if (event.key === "Escape")
            hide();
    });
    // A fixed node does not follow its trigger, so retire it instead of
    // letting it drift.
    window.addEventListener("scroll", () => hide(), true);
    window.addEventListener("resize", () => hide());
}
export default initTooltips;
